CustomField.formula:
IF(
    AND(
        ISPICKVAL(Status__c, "Closed"),
        NOT(ISBLANK(Closed_Date__c))
    ),

    TEXT(FLOOR(Closed_Date__c - CreatedDate)) & " Days " &

    TEXT(
        FLOOR(
            MOD((Closed_Date__c - CreatedDate) * 24, 24)
        )
    ) & " Hours " &

    TEXT(
        FLOOR(
            MOD((Closed_Date__c - CreatedDate) * 1440, 60)
        )
    ) & " Minutes",

    NULL
)
